sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    /* ========================================================
       CAMPUS360 SIDEBAR
       ======================================================== */

    c.sidebarOpen = true;
    c.loading = false;


    /* ========================================================
       STUDENT INITIALS
       ======================================================== */

    c.getStudentInitials = function() {

        var name =
            c.data &&
            c.data.student &&
            c.data.student.name
                ? String(c.data.student.name)
                : 'Test Student';

        var parts = name.trim().split(/\s+/);

        if (!parts.length) {
            return 'TS';
        }

        if (parts.length === 1) {
            return parts[0]
                .substring(0, 2)
                .toUpperCase();
        }

        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();
    };


    /* ========================================================
       SIDEBAR TOGGLE
       ======================================================== */

    c.toggleSidebar = function() {

        c.sidebarOpen = !c.sidebarOpen;

    };


    /* ========================================================
       STUDENT ID
       ======================================================== */

    c.getStudentId = function() {

        var student = 'STU_TEST_001';

        if (
            c.data &&
            c.data.student &&
            c.data.student.id
        ) {

            student =
                c.data.student.id;

        }

        return student;

    };


    /* ========================================================
       NAVIGATION
       ======================================================== */

    c.navigate = function(pageId) {

        if (!pageId) {
            return;
        }

        var student =
            c.getStudentId();

        var url =
            '?id=' +
            encodeURIComponent(pageId) +
            '&student=' +
            encodeURIComponent(student);

        $window.location.href = url;

    };


    /* ========================================================
       DASHBOARD
       ======================================================== */

    c.goToDashboard = function() {

        c.navigate(
            'campus360_student_dashboard'
        );

    };


    /* ========================================================
       RISK
       ======================================================== */

    c.getRiskClass = function(risk) {

        var value =
            String(
                risk || ''
            ).toLowerCase();


        if (value === 'low') {

            return 'cr-risk-low';

        }


        if (
            value === 'medium' ||
            value === 'moderate'
        ) {

            return 'cr-risk-medium';

        }


        if (
            value === 'high' ||
            value === 'critical'
        ) {

            return 'cr-risk-high';

        }


        return 'cr-risk-medium';

    };


    /* ========================================================
       INTERVENTION STATUS
       ======================================================== */

    c.getStatusClass = function(status) {

        var value =
            String(
                status || ''
            ).toLowerCase();


        if (
            value.indexOf('complete') !== -1
        ) {

            return 'cr-status-completed';

        }


        if (
            value.indexOf('progress') !== -1 ||
            value.indexOf('active') !== -1
        ) {

            return 'cr-status-progress';

        }


        if (
            value.indexOf('open') !== -1 ||
            value.indexOf('pending') !== -1
        ) {

            return 'cr-status-open';

        }


        return 'cr-status-default';

    };


    /* ========================================================
       INTERESTED
       EXACT EXISTING SERVER FLOW
       ======================================================== */

    c.interested = function(training) {

        if (
            !training ||
            !training.sys_id ||
            training.processing
        ) {

            return;

        }


        training.processing = true;


        c.server.get({

            action:
                'interested_training',

            trainingSysId:
                training.sys_id

        }).then(

            function(response) {

                training.processing = false;


                if (
                    response &&
                    response.data &&
                    response.data.success === true
                ) {

                    training.enrolled = true;

                    training.ignored = false;

                    training.message =
                        response.data.message ||
                        'Interest recorded. You will be enrolled by the TPO.';

                } else {

                    alert(
                        response &&
                        response.data &&
                        response.data.message
                            ?
                            response.data.message
                            :
                            'Unable to record your interest.'
                    );

                }

            },

            function() {

                training.processing = false;

                alert(
                    'Unable to contact the server. Please try again.'
                );

            }

        );

    };


    /* ========================================================
       IGNORE
       ======================================================== */

    c.ignoreTraining = function(training) {

        if (!training) {
            return;
        }

        training.ignored = true;

    };


    /* ========================================================
       RESTORE
       ======================================================== */

    c.restoreTraining = function(training) {

        if (!training) {
            return;
        }

        training.ignored = false;

    };


    /* ========================================================
       REFRESH
       EXACT EXISTING SERVER FLOW
       ======================================================== */

    c.refresh = function() {

        if (c.loading) {
            return;
        }


        c.loading = true;


        c.server.refresh().then(

            function() {

                c.loading = false;

            },

            function() {

                c.loading = false;

            }

        );

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 PLACEMENT READINESS
   FINAL STUDENT PORTAL STYLE
   UPDATED:
   - LEFT SIDEBAR = DARK PURPLE
   - PLACEMENT READINESS TOP CARD = DARK PURPLE
   - TOP CAMPUS360 NAVBAR = WHITE
   ========================================================= */


/* =========================================================
   SERVICENOW DEFAULT HEADER
   HIDE SYSTEM ADMINISTRATOR NAVBAR
   ========================================================= */

body:has(.campus360-readiness-page) #sp-header,
body:has(.campus360-readiness-page) .sp-header,
body:has(.campus360-readiness-page) .sp-navbar,
body:has(.campus360-readiness-page) .navbar.sp-navbar,
body:has(.campus360-readiness-page) #sp-nav-bar,
body:has(.campus360-readiness-page) .sp-nav-bar,
body:has(.campus360-readiness-page) header#sp-header,
body:has(.campus360-readiness-page) header.sp-header {

    display: none !important;

}


body:has(.campus360-readiness-page) #sp-page,
body:has(.campus360-readiness-page) #sp-main {

    margin-top: 0 !important;

    padding-top: 0 !important;

}


/* =========================================================
   SERVICENOW WRAPPER RESET
   ========================================================= */

.well:has(.campus360-readiness-page),
.panel:has(.campus360-readiness-page) {

    width: 100% !important;

    max-width: none !important;

    margin: 0 !important;

    padding: 0 !important;

    border: 0 !important;

    background: transparent !important;

    box-shadow: none !important;

}


.panel:has(.campus360-readiness-page) .panel-body {

    width: 100% !important;

    margin: 0 !important;

    padding: 0 !important;

}


.row:has(.campus360-readiness-page) {

    margin-left: 0 !important;

    margin-right: 0 !important;

}


/* =========================================================
   ROOT
   ========================================================= */

.campus360-readiness-page {

    position: fixed !important;

    inset: 0 !important;

    width: 100vw !important;

    height: 100vh !important;

    min-height: 100vh !important;

    max-width: 100vw !important;

    max-height: 100vh !important;

    margin: 0 !important;

    padding: 0 !important;

    overflow: hidden !important;

    display: block !important;

    background:
        linear-gradient(
            135deg,
            #f2f5fa 0%,
            #f7f5fc 50%,
            #f2f8f8 100%
        );

    color: #152840;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        Helvetica,
        sans-serif;

    z-index: 999999 !important;

}


.campus360-readiness-page,
.campus360-readiness-page *,
.campus360-readiness-page *::before,
.campus360-readiness-page *::after {

    box-sizing: border-box;

}


/* =========================================================
   LEFT SIDEBAR
   DARK PURPLE
   ========================================================= */

.c360-left-sidebar {

    position: absolute !important;

    top: 0;

    left: 0;

    bottom: 0;

    width: 242px !important;

    min-width: 242px !important;

    max-width: 242px !important;

    height: 100vh !important;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    background:
        linear-gradient(
            180deg,
            #130d2f 0%,
            #160d38 48%,
            #100a29 100%
        ) !important;

    border-right:
        1px
        solid
        #2d2157 !important;

    box-shadow:
        4px 0 16px
        rgba(25,10,60,.20);

    z-index: 5000;

    transition:
        transform .25s ease;

}


.campus360-readiness-page.sidebar-closed
.c360-left-sidebar {

    transform:
        translateX(-105%);

}


/* =========================================================
   BRAND
   ========================================================= */

.c360-sidebar-brand {

    height: 78px;

    min-height: 78px;

    padding:
        0
        14px;

    display: flex;

    align-items: center;

    gap: 11px;

    border-bottom:
        1px
        solid
        #2d2157;

    background:
        #130d2f !important;

}


.c360-brand-logo {

    width: 40px;

    height: 40px;

    min-width: 40px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    background:
        linear-gradient(
            135deg,
            #7c3aed,
            #9333ea
        );

    color: #ffffff;

    font-size: 18px;

    font-weight: 900;

    box-shadow:
        0
        7px
        16px
        rgba(124,58,237,.30);

}


.c360-brand-name {

    display: flex;

    flex-direction: column;

    white-space: nowrap;

}


.c360-brand-name strong {

    color: #ffffff;

    font-size: 16px;

    font-weight: 900;

}


.c360-brand-name span {

    margin-top: 3px;

    color: #c4b5fd;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: .7px;

}


/* =========================================================
   STUDENT SIDEBAR CARD
   ========================================================= */

.c360-sidebar-student {

    position: relative;

    margin:
        15px
        10px
        9px;

    padding:
        10px;

    min-height: 63px;

    display: flex;

    align-items: center;

    gap: 10px;

    border:
        1px
        solid
        #3a2d68;

    border-radius: 11px;

    background:
        #1d1440;

    color: inherit !important;

    text-decoration: none !important;

}


.c360-sidebar-student:hover {

    border-color: #6246a8;

    background:
        #24174d;

}


.c360-sidebar-avatar {

    width: 38px;

    height: 38px;

    min-width: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #7c5ce8,
            #6d4fe1
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 900;

}


.c360-sidebar-student-info {

    min-width: 0;

    flex: 1;

}


.c360-sidebar-student-info strong {

    display: block;

    max-width: 160px;

    overflow: hidden;

    white-space: nowrap;

    text-overflow: ellipsis;

    color: #ffffff;

    font-size: 12px;

    font-weight: 850;

}


.c360-sidebar-student-info span {

    display: block;

    margin-top: 3px;

    color: #aaa0c7;

    font-size: 9px;

}


.c360-student-arrow {

    color: #a99fc7;

    font-size: 20px;

}


/* =========================================================
   SIDEBAR NAV
   ========================================================= */

.c360-sidebar-nav {

    flex:
        1
        1
        auto;

    min-height: 0;

    padding:
        2px
        9px
        12px;

    overflow-y: auto;

    overflow-x: hidden;

}


.c360-sidebar-nav::-webkit-scrollbar {

    width: 5px;

}


.c360-sidebar-nav::-webkit-scrollbar-track {

    background: transparent;

}


.c360-sidebar-nav::-webkit-scrollbar-thumb {

    background: #40326e;

    border-radius: 10px;

}


.c360-nav-group {

    margin-bottom: 5px;

}


.c360-nav-heading {

    padding:
        11px
        10px
        6px;

    color: #8f84ae;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: 1.25px;

}


.c360-nav-link {

    position: relative;

    width: 100%;

    min-height: 40px;

    margin:
        2px
        0;

    padding:
        7px
        11px;

    display: flex;

    align-items: center;

    gap: 10px;

    border: 0;

    border-radius: 8px;

    background: transparent;

    color: #d8d0eb !important;

    font-family: inherit;

    font-size: 13px;

    font-weight: 650;

    text-align: left;

    cursor: pointer;

    transition:
        background .16s ease,
        color .16s ease,
        transform .16s ease;

}


.c360-nav-link:hover {

    background:
        rgba(124,58,237,.18);

    color: #ffffff !important;

    transform:
        translateX(1px);

}


.c360-nav-link.active {

    background:
        linear-gradient(
            135deg,
            #7c3aed,
            #8b3ff2
        );

    color: #ffffff !important;

    font-weight: 850;

    box-shadow:
        0
        6px
        13px
        rgba(124,58,237,.24);

}


.c360-nav-link.active::before {

    display: none;

}


.c360-nav-icon {

    width: 19px;

    min-width: 19px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    color: #a99fc7;

    font-size: 14px;

}


.c360-nav-link:hover
.c360-nav-icon {

    color: #ffffff;

}


.c360-nav-link.active
.c360-nav-icon {

    color: #ffffff;

}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {

    height: 70px;

    min-height: 70px;

    margin:
        0
        10px
        10px;

    padding:
        10px
        11px;

    border:
        1px
        solid
        #3a2d68;

    border-radius: 10px;

    background:
        #1a1138;

}


.c360-footer-title {

    color: #9d91b8;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1px;

}


.c360-readiness-track {

    width: 100%;

    height: 6px;

    margin-top: 8px;

    overflow: hidden;

    border-radius: 10px;

    background: #302454;

}


.c360-readiness-fill {

    height: 100%;

    border-radius: inherit;

    background:
        linear-gradient(
            90deg,
            #7c3aed,
            #a855f7
        );

    transition:
        width .3s ease;

}


.c360-readiness-text {

    margin-top: 5px;

    color: #9d91b8;

    font-size: 9px;

    font-weight: 700;

}


/* =========================================================
   SIDEBAR OVERLAY
   ========================================================= */

.c360-sidebar-overlay {

    display: none;

}


/* =========================================================
   RIGHT PAGE
   ========================================================= */

.c360-right-page {

    position: absolute !important;

    top: 0;

    right: 0;

    bottom: 0;

    left: 242px;

    width: auto !important;

    height: 100vh !important;

    min-width: 0 !important;

    overflow-y: auto !important;

    overflow-x: hidden !important;

    background:
        linear-gradient(
            135deg,
            #f1f6fc 0%,
            #f7f4ff 50%,
            #f0f8f6 100%
        );

    transition:
        left .25s ease;

}


.campus360-readiness-page.sidebar-closed
.c360-right-page {

    left: 0;

}


/* =========================================================
   TOP NAVBAR
   WHITE
   ========================================================= */

.c360-topbar {

    position: sticky;

    top: 0;

    z-index: 6000;

    width: 100%;

    height: 70px;

    min-height: 70px;

    padding:
        0
        17px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    background: #ffffff !important;

    border-bottom:
        1px
        solid
        #dfe6ee;

    box-shadow:
        0
        2px
        7px
        rgba(25,43,60,.025);

}


.c360-topbar-left {

    min-width: 0;

    display: flex;

    align-items: center;

    gap: 13px;

}


.c360-menu-button {

    width: 40px;

    height: 40px;

    min-width: 40px;

    padding: 0;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    gap: 5px;

    border:
        1px
        solid
        #d6dfeb;

    border-radius: 10px;

    background: #ffffff;

    cursor: pointer;

    box-shadow:
        0
        2px
        5px
        rgba(25,43,60,.035);

}


.c360-menu-button:hover {

    background: #f7f4ff;

    border-color: #cfc2fa;

}


.c360-menu-button span {

    width: 19px;

    height: 2px;

    display: block;

    border-radius: 3px;

    background: #7040ff;

}


.c360-page-heading {

    min-width: 0;

    display: flex;

    flex-direction: column;

}


.c360-page-heading span {

    color: #7040ff;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1.5px;

}


.c360-page-heading strong {

    margin-top: 4px;

    color: #152a43;

    font-size: 14px;

    font-weight: 850;

}


.c360-topbar-right {

    margin-left: auto;

    display: flex;

    align-items: center;

    gap: 9px;

}


.c360-top-icon {

    position: relative;

    width: 40px;

    height: 40px;

    min-width: 40px;

    padding: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px
        solid
        #d7e0eb;

    border-radius: 10px;

    background: #ffffff;

    color: #63748a;

    cursor: pointer;

}


.c360-top-icon:hover {

    color: #7040ff;

    background: #f7f4ff;

    border-color: #cdc3ee;

}


.c360-top-icon:disabled {

    opacity: .55;

    cursor: not-allowed;

}


.c360-top-icon .fa {

    font-size: 15px;

}


.c360-notification-dot {

    position: absolute;

    top: 7px;

    right: 7px;

    width: 6px;

    height: 6px;

    border-radius: 50%;

    background: #ff4d67;

    border:
        1px
        solid
        #ffffff;

}


.c360-top-student {

    min-height: 43px;

    padding-left:
        10px;

    display: flex;

    align-items: center;

    gap: 8px;

    border-left:
        1px
        solid
        #e2e6ee;

    color: inherit !important;

    text-decoration: none !important;

}


.c360-top-avatar {

    width: 37px;

    height: 37px;

    min-width: 37px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background:
        linear-gradient(
            135deg,
            #7040ff,
            #8152ff
        );

    color: #ffffff;

    font-size: 11px;

    font-weight: 900;

}


.c360-top-student-info {

    min-width: 0;

    display: flex;

    flex-direction: column;

}


.c360-top-student-info strong {

    display: block;

    max-width: 180px;

    overflow: hidden;

    white-space: nowrap;

    text-overflow: ellipsis;

    color: #26374c;

    font-size: 11px;

    font-weight: 850;

}


.c360-top-student-info span {

    margin-top: 2px;

    color: #8a97a8;

    font-size: 8px;

}


.c360-top-chevron {

    color: #77859a;

    font-size: 13px;

}


/* =========================================================
   PAGE CONTENT
   ========================================================= */

.c360-page-content {

    width: 100%;

    min-width: 0;

}


/* =========================================================
   PAGE SHELL
   ========================================================= */

.cr-page-shell {

    width: 100%;

    min-height:
        calc(100vh - 70px);

    display: grid;

    grid-template-columns:
        minmax(0,1fr)
        390px;

    align-items: start;

}


.cr-main-content {

    width: 100%;

    min-width: 0;

    padding:
        20px
        20px
        45px;

    background: #f4f7fb;

}


/* =========================================================
   PLACEMENT READINESS TOP CARD
   DARK PURPLE
   ========================================================= */

.cr-student-header {

    position: relative;

    z-index: 1;

    width: 100%;

    min-height: 116px;

    padding:
        20px
        22px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    background:
        linear-gradient(
            135deg,
            #241044 0%,
            #32145b 52%,
            #45206d 100%
        ) !important;

    border:
        1px
        solid
        #5a357d;

    border-radius: 16px;

    box-shadow:
        0
        10px
        26px
        rgba(50,20,80,.18);

}


.cr-student-left {

    min-width: 0;

    display: flex;

    align-items: center;

    gap: 15px;

}


.cr-student-avatar {

    width: 60px;

    height: 60px;

    min-width: 60px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 15px;

    background:
        linear-gradient(
            135deg,
            #8b5cf6,
            #7c3aed
        );

    color: #ffffff;

    font-size: 18px;

    font-weight: 900;

    box-shadow:
        0
        7px
        18px
        rgba(0,0,0,.18);

}


.cr-student-information {

    min-width: 0;

}


.cr-student-name-row {

    display: flex;

    align-items: center;

    flex-wrap: wrap;

    gap: 8px;

}


.cr-student-name-row h1 {

    margin: 0;

    color: #ffffff;

    font-size: 24px;

    line-height: 1.2;

    font-weight: 900;

}


.cr-student-id {

    padding:
        5px
        8px;

    border:
        1px
        solid
        rgba(255,255,255,.20);

    border-radius: 6px;

    background:
        rgba(255,255,255,.12);

    color: #e9ddff;

    font-size: 9px;

    font-weight: 850;

}


.cr-student-meta {

    margin-top: 7px;

    color: #d6cbe4;

    font-size: 12px;

    line-height: 1.5;

    font-weight: 600;

}


.cr-risk-area {

    flex-shrink: 0;

    min-width: 155px;

    text-align: right;

}


.cr-risk-label {

    margin-bottom: 6px;

    color: #c5b7d8;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: .55px;

}


.cr-risk-badge {

    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding:
        7px
        12px;

    border-radius: 20px;

    font-size: 11px;

    font-weight: 900;

}


.cr-risk-dot {

    width: 8px;

    height: 8px;

    border-radius: 50%;

    background: currentColor;

}


.cr-risk-low {

    color: #b9f3d0;

    background:
        rgba(22,163,74,.18);

    border:
        1px
        solid
        rgba(134,239,172,.35);

}


.cr-risk-medium {

    color: #fde68a;

    background:
        rgba(180,83,9,.18);

    border:
        1px
        solid
        rgba(253,230,138,.30);

}


.cr-risk-high {

    color: #fecaca;

    background:
        rgba(185,28,28,.18);

    border:
        1px
        solid
        rgba(252,165,165,.30);

}


/* =========================================================
   ALL REMAINING PLACEMENT READINESS CSS
   ========================================================= */

.cr-summary-grid {

    width: 100%;

    margin-top: 17px;

    display: grid;

    grid-template-columns:
        1.1fr
        1fr
        1fr
        1fr
        1fr;

    gap: 10px;

}


.cr-summary-card {

    min-width: 0;

    min-height: 145px;

    padding: 16px;

    border:
        1px
        solid
        #d8e2ed;

    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0
        4px
        12px
        rgba(18,42,75,.04);

}


.cr-readiness-card {

    background:
        linear-gradient(
            145deg,
            #5145d8,
            #392bb3
        );

    border-color: #473bc7;

}


.cr-summary-label {

    color: #68788c;

    font-size: 9px;

    font-weight: 900;

    letter-spacing: .65px;

}


.cr-readiness-card
.cr-summary-label {

    color: #dedcff;

}


.cr-readiness-number {

    margin-top: 8px;

    color: #ffffff;

    font-size: 34px;

    line-height: 1;

    font-weight: 900;

}


.cr-readiness-number span {

    color: #d9d7ff;

    font-size: 12px;

}


.cr-summary-description {

    margin-top: 9px;

    color: #eeeeff;

    font-size: 10px;

    line-height: 1.45;

}


.cr-mini-progress {

    height: 5px;

    margin-top: 10px;

    overflow: hidden;

    border-radius: 10px;

    background:
        rgba(255,255,255,.24);

}


.cr-mini-progress-fill {

    height: 100%;

    border-radius: inherit;

    background: #ffffff;

}


.cr-skill-card {

    border-top:
        4px
        solid
        #8b43e8;

}


.cr-bottleneck-card {

    border-top:
        4px
        solid
        #e39415;

}


.cr-participation-card {

    border-top:
        4px
        solid
        #10a875;

}


.cr-missed-card {

    border-top:
        4px
        solid
        #e57c18;

}


.cr-summary-main-value {

    margin-top: 12px;

    color: #172238;

    font-size: 18px;

    line-height: 1.25;

    font-weight: 900;

    word-break: break-word;

}


.cr-summary-number {

    margin-top: 12px;

    color: #172238;

    font-size: 28px;

    line-height: 1;

    font-weight: 900;

}


.cr-summary-number span {

    color: #65748a;

    font-size: 11px;

}


.cr-summary-bottom {

    margin-top: 17px;

    font-size: 10px;

    font-weight: 850;

}


.skill-bottom {
    color: #7037bf;
}

.bottleneck-bottom {
    color: #b46a05;
}

.participation-bottom {
    color: #087c50;
}

.missed-bottom {
    color: #b65c10;
}


.cr-summary-bottom i {
    margin-right: 5px;
}


/* =========================================================
   SECTIONS
   ========================================================= */

.cr-section,
.cr-analysis-section {

    width: 100%;

    margin-top: 18px;

    padding: 20px;

    border:
        1px
        solid
        #d8e2ed;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0
        4px
        14px
        rgba(18,42,75,.04);

}


.cr-section-header {

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 15px;

    padding-bottom: 14px;

    border-bottom:
        1px
        solid
        #e0e7ef;

}


.cr-section-kicker {

    margin-bottom: 5px;

    color: #5146d5;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 1.1px;

}


.cr-section-title {

    margin: 0;

    color: #142033;

    font-size: 22px;

    font-weight: 900;

}


.cr-section-description {

    margin-top: 5px;

    color: #607086;

    font-size: 11px;

    line-height: 1.5;

}


.cr-analysis-status {

    padding-top: 6px;

    color: #657489;

    font-size: 10px;

    font-weight: 800;

}


.cr-analysis-status span {

    width: 8px;

    height: 8px;

    display: inline-block;

    margin-right: 5px;

    border-radius: 50%;

    background: #12ad7a;

}


/* =========================================================
   AI ANALYSIS
   ========================================================= */

.cr-analysis-cards {

    margin-top: 16px;

    display: grid;

    grid-template-columns:
        repeat(3,minmax(0,1fr));

    gap: 11px;

}


.cr-ai-card {

    min-height: 180px;

    padding: 16px;

    border:
        1px
        solid;

    border-radius: 13px;

}


.cr-ai-insight {

    background: #f1f4ff;

    border-color: #bcc7f1;

}


.cr-ai-gap {

    background: #fff9e9;

    border-color: #efd98a;

}


.cr-ai-action {

    background: #eefbf5;

    border-color: #a8dec2;

}


.cr-ai-icon {

    width: 40px;

    height: 40px;

    margin-bottom: 12px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

}


.cr-ai-insight .cr-ai-icon {

    background: #dce3ff;

    color: #4238c1;

}


.cr-ai-gap .cr-ai-icon {

    background: #ffedb2;

    color: #a56304;

}


.cr-ai-action .cr-ai-icon {

    background: #cef5df;

    color: #08794f;

}


.cr-ai-card-title {

    color: #172238;

    font-size: 15px;

    font-weight: 900;

}


.cr-ai-card-text {

    margin-top: 8px;

    color: #334258;

    font-size: 11px;

    line-height: 1.6;

}


/* =========================================================
   INTERVENTION
   ========================================================= */

.cr-intervention-card {

    margin-top: 17px;

    padding: 17px;

    border:
        1px
        solid
        #cad7e6;

    border-left:
        5px
        solid
        #3570d1;

    border-radius: 12px;

    background: #ffffff;

}


.cr-intervention-top {

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    gap: 15px;

    padding-bottom: 14px;

    border-bottom:
        1px
        solid
        #dce5ef;

}


.cr-intervention-title {

    color: #172238;

    font-size: 15px;

    font-weight: 900;

}


.cr-intervention-reason {

    margin-top: 4px;

    color: #627085;

    font-size: 11px;

    line-height: 1.5;

}


.cr-intervention-status {

    padding:
        6px
        10px;

    border-radius: 16px;

    font-size: 9px;

    font-weight: 900;

}


.cr-intervention-details {

    margin-top: 14px;

    display: grid;

    grid-template-columns:
        repeat(4,minmax(0,1fr));

    gap: 9px;

}


.cr-intervention-detail {

    min-height: 66px;

    padding: 10px;

    border:
        1px
        solid
        #d8e2ed;

    border-radius: 9px;

    background: #f5f8fb;

}


.cr-score-detail {

    background: #eef5ff;

    border-color: #cadcf4;

}


.cr-detail-label {

    color: #68788c;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: .55px;

}


.cr-detail-value {

    margin-top: 5px;

    color: #17243a;

    font-size: 11px;

    line-height: 1.35;

    font-weight: 800;

}


.cr-score-value {

    margin-top: 3px;

    color: #1858a8;

    font-size: 19px;

    font-weight: 900;

}


.cr-empty-card {

    margin-top: 15px;

    padding: 15px;

    border:
        1px
        dashed
        #c8d5e3;

    border-radius: 11px;

    background: #f8fafc;

    color: #607086;

    font-size: 11px;

}


/* =========================================================
   TRAINING
   ========================================================= */

.cr-match-badge {

    display: inline-flex;

    align-items: center;

    gap: 5px;

    padding:
        6px
        9px;

    border:
        1px
        solid
        #c5d8f3;

    border-radius: 8px;

    background: #edf3ff;

    color: #245a9f;

    font-size: 9px;

    font-weight: 850;

}


.cr-training-grid {

    margin-top: 17px;

    display: grid;

    grid-template-columns:
        repeat(2,minmax(0,1fr));

    gap: 11px;

}


.cr-training-card {

    min-width: 0;

    padding: 16px;

    border:
        1px
        solid
        #cad9e7;

    border-radius: 13px;

    background: #ffffff;

}


.cr-training-card-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

}


.cr-training-icon {

    width: 42px;

    height: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    background: #e2efff;

    color: #1d5dab;

}


.cr-training-status {

    padding:
        5px
        9px;

    border-radius: 14px;

    background: #e7f8ee;

    color: #08794d;

    font-size: 9px;

    font-weight: 900;

}


.cr-training-name {

    margin-top: 12px;

    color: #152238;

    font-size: 16px;

    font-weight: 900;

}


.cr-training-id {

    margin-top: 3px;

    color: #6d7c8e;

    font-size: 9px;

}


.cr-training-information {

    margin-top: 13px;

    display: grid;

    grid-template-columns:
        repeat(2,minmax(0,1fr));

    gap: 7px;

}


.cr-training-information-item {

    padding: 9px;

    border:
        1px
        solid
        #dce4ec;

    border-radius: 8px;

    background: #f4f7fa;

}


.cr-training-information-label {

    color: #68788c;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: .5px;

}


.cr-training-information-value {

    margin-top: 4px;

    color: #1e2e43;

    font-size: 10px;

    line-height: 1.35;

    font-weight: 800;

}


.cr-training-actions {

    margin-top: 15px;

    display: flex;

    gap: 8px;

}


.cr-interested-button,
.cr-ignore-button {

    min-height: 39px;

    border-radius: 9px;

    font-size: 11px;

    font-weight: 850;

    cursor: pointer;

}


.cr-interested-button {

    flex: 1;

    border:
        1px
        solid
        #087a50;

    background: #0d9c68;

    color: #ffffff;

}


.cr-ignore-button {

    min-width: 85px;

    border:
        1px
        solid
        #c5d0dc;

    background: #ffffff;

    color: #536276;

}


.cr-training-success {

    margin-top: 15px;

    padding: 10px;

    display: flex;

    align-items: center;

    gap: 7px;

    border:
        1px
        solid
        #b8e5ca;

    border-radius: 9px;

    background: #e9f9f0;

    color: #08784e;

    font-size: 10px;

    font-weight: 800;

}


.cr-training-ignored-message {

    margin-top: 15px;

    padding: 10px;

    display: flex;

    align-items: center;

    gap: 7px;

    border:
        1px
        solid
        #d6dee6;

    border-radius: 9px;

    background: #f2f4f7;

    color: #677486;

    font-size: 10px;

}


.cr-training-ignored-message button {

    margin-left: auto;

    border: 0;

    background: transparent;

    color: #1d5cac;

    font-size: 10px;

    font-weight: 850;

    cursor: pointer;

}


.cr-no-training {

    margin-top: 16px;

    padding: 30px;

    text-align: center;

    border:
        1px
        dashed
        #c9d5e2;

    border-radius: 13px;

    background: #f9fbfd;

}


.cr-no-training-icon {

    width: 45px;

    height: 45px;

    margin:
        auto;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #eaf1f8;

    color: #47719e;

}


.cr-no-training-title {

    margin-top: 10px;

    color: #1b2a3f;

    font-size: 15px;

    font-weight: 900;

}


.cr-no-training-description {

    max-width: 550px;

    margin:
        6px
        auto
        0;

    color: #647488;

    font-size: 11px;

    line-height: 1.5;

}


/* =========================================================
   FOOTER
   ========================================================= */

.cr-footer {

    padding:
        20px
        0
        0;

    text-align: center;

}


.cr-dashboard-footer {

    min-height: 40px;

    padding:
        0
        15px;

    border:
        1px
        solid
        #c7d4e2;

    border-radius: 9px;

    background: #ffffff;

    color: #315d91;

    font-size: 11px;

    font-weight: 850;

    cursor: pointer;

}


/* =========================================================
   CAMPUSAI SIDEBAR
   UNCHANGED
   ========================================================= */

.cr-ai-sidebar {

    position: sticky !important;

    top: 70px !important;

    align-self: start !important;

    width: 100%;

    height:
        calc(100vh - 70px) !important;

    min-height:
        calc(100vh - 70px) !important;

    max-height:
        calc(100vh - 70px) !important;

    overflow: hidden;

    background:
        linear-gradient(
            180deg,
            #f8fdff 0%,
            #eaf7fd 48%,
            #e3f4fc 100%
        );

    border-left:
        1px
        solid
        #cfe1ec;

    z-index: 100;

}


.cr-ai-sidebar-inner {

    position: relative;

    width: 100%;

    height:
        calc(100vh - 70px) !important;

    min-height:
        calc(100vh - 70px) !important;

    max-height:
        calc(100vh - 70px) !important;

    padding:
        17px
        18px
        12px;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    background:
        linear-gradient(
            180deg,
            rgba(255,255,255,.98) 0%,
            rgba(246,252,255,.96) 42%,
            rgba(229,245,253,.98) 100%
        );

}


.cr-ai-sidebar-header {

    flex:
        0
        0
        auto;

    display: flex;

    align-items: center;

    gap: 7px;

    padding-bottom:
        11px;

    border-bottom:
        1px
        solid
        #d7e7ef;

}


.cr-ai-status-dot {

    width: 9px;

    height: 9px;

    border-radius: 50%;

    background: #13bd91;

    box-shadow:
        0
        0
        9px
        rgba(19,189,145,.35);

}


.cr-ai-sidebar-title {

    color: #1b3447;

    font-size: 12px;

    font-weight: 900;

    letter-spacing: .55px;

}


.cr-ai-version {

    margin-left: auto;

    padding:
        5px
        8px;

    border:
        1px
        solid
        #c5dce9;

    border-radius: 12px;

    background: #f0f8fc;

    color: #688095;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: .55px;

}


.cr-robot-stage {

    position: relative;

    flex:
        1
        1
        auto;

    min-height: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    padding:
        8px
        0;

}


.cr-robot-card {

    position: relative;

    z-index: 2;

    width:
        min(100%,330px);

    height:
        min(60vh,500px);

    min-height: 365px;

    padding:
        11px;

    display: flex;

    flex-direction: column;

    justify-content: center;

    align-items: center;

    border:
        1px
        solid
        #c9e0ec;

    border-radius: 19px;

    background:
        linear-gradient(
            145deg,
            #ffffff 0%,
            #f8fcff 42%,
            #eaf7fd 100%
        );

    box-shadow:
        0
        12px
        28px
        rgba(62,112,145,.09);

    overflow: hidden;

}


.cr-robot-card::before {

    content: "";

    position: absolute;

    left: 50%;

    top: 45%;

    width: 240px;

    height: 240px;

    transform:
        translate(-50%,-50%);

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(101,190,230,.13) 0%,
            rgba(139,209,237,.06) 45%,
            rgba(255,255,255,0) 75%
        );

    pointer-events: none;

}


.cr-robot-image-wrap {

    position: relative;

    z-index: 2;

    width: 100%;

    height:
        calc(100% - 49px);

    min-height: 295px;

    display: flex;

    align-items: center;

    justify-content: center;

    overflow: hidden;

    border-radius: 14px;

    background:
        linear-gradient(
            145deg,
            #ffffff,
            #eff9ff
        );

}


.cr-reference-robot {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: cover;

    object-position: center;

    border-radius: 14px;

    background: #eef9ff;

}


.cr-robot-caption {

    position: relative;

    z-index: 4;

    padding:
        8px
        0
        1px;

    display: flex;

    flex-direction: column;

    align-items: center;

    text-align: center;

}


.cr-robot-caption strong {

    color: #18344a;

    font-size: 13px;

    font-weight: 900;

}


.cr-robot-caption span {

    margin-top: 3px;

    color: #71889a;

    font-size: 8px;

    font-weight: 650;

}


.cr-robot-metric {

    position: absolute;

    z-index: 10;

    min-width: 100px;

    max-width: 120px;

    padding:
        8px
        9px;

    border:
        1px
        solid
        #c9dce8;

    border-radius: 10px;

    background:
        rgba(255,255,255,.97);

    box-shadow:
        0
        6px
        15px
        rgba(32,66,91,.10);

}


.metric-left-top {

    top: 8%;

    left: 0;

}


.metric-right-top {

    top: 13%;

    right: 0;

}


.metric-left-bottom {

    bottom: 10%;

    left: 0;

}


.metric-right-bottom {

    bottom: 7%;

    right: 0;

}


.cr-metric-title {

    color: #76899a;

    font-size: 8px;

    font-weight: 800;

}


.cr-metric-title i {

    color: #5588a6;

    margin-right: 3px;

}


.cr-metric-value {

    margin-top: 3px;

    color: #19364b;

    font-size: 14px;

    font-weight: 900;

}


.cr-metric-value span {

    color: #8195a6;

    font-size: 8px;

}


.cr-metric-small {

    display: inline-block;

    margin-top: 2px;

    color: #a06f0b;

    font-size: 7px;

    font-weight: 900;

}


.skill-metric {

    max-width: 100px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    color: #5146d5;

}


.cr-ai-status-card {

    flex:
        0
        0
        auto;

    display: flex;

    align-items: flex-start;

    gap: 9px;

    padding:
        10px;

    border:
        1px
        solid
        #cadee9;

    border-radius: 11px;

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #eef9ff
        );

}


.cr-ai-status-card-icon {

    width: 34px;

    height: 34px;

    min-width: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px
        solid
        #cbdcf4;

    border-radius: 9px;

    background: #edf1ff;

    color: #5146e5;

}


.cr-ai-status-card-content {

    min-width: 0;

}


.cr-ai-status-card-title {

    color: #1c3348;

    font-size: 10px;

    font-weight: 900;

}


.cr-ai-status-card-text {

    margin-top: 4px;

    color: #718597;

    font-size: 8px;

    line-height: 1.45;

}


.cr-ai-sidebar-footer {

    flex:
        0
        0
        auto;

    margin-top: 7px;

    text-align: center;

    color: #879aaa;

    font-size: 7px;

    font-weight: 800;

    letter-spacing: .5px;

    text-transform: uppercase;

}


.cr-ai-sidebar-footer span {

    width: 5px;

    height: 5px;

    display: inline-block;

    margin-right: 4px;

    border-radius: 50%;

    background: #15c99b;

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width:1250px) {

    .cr-page-shell {

        grid-template-columns:
            minmax(0,1fr)
            340px;

    }

    .cr-summary-grid {

        grid-template-columns:
            repeat(3,minmax(0,1fr));

    }

    .cr-analysis-cards {

        grid-template-columns:
            1fr;

    }

    .cr-intervention-details {

        grid-template-columns:
            repeat(3,minmax(0,1fr));

    }

}


@media (max-width:1000px) {

    .c360-left-sidebar {

        position: fixed !important;

        top: 0;

        left: 0;

        bottom: 0;

        width: 250px !important;

        min-width: 250px !important;

        max-width: 250px !important;

        z-index: 9000;

        background:
            linear-gradient(
                180deg,
                #130d2f 0%,
                #160d38 48%,
                #100a29 100%
            ) !important;

    }


    .c360-right-page {

        left: 0 !important;

        width: 100% !important;

    }


    .campus360-readiness-page.sidebar-open
    .c360-sidebar-overlay {

        display: block;

        position: fixed;

        inset: 0;

        z-index: 8500;

        background:
            rgba(15,23,42,.34);

    }


    .cr-page-shell {

        display: block;

    }


    .cr-main-content {

        padding:
            18px
            18px
            40px;

    }


    .cr-ai-sidebar {

        position: relative !important;

        top: auto !important;

        width: 100%;

        height: 620px !important;

        min-height: 620px !important;

        max-height: 620px !important;

        border-left: 0;

        border-top:
            1px
            solid
            #cfe1ec;

    }


    .cr-ai-sidebar-inner {

        height: 620px !important;

        min-height: 620px !important;

        max-height: 620px !important;

    }


    .cr-summary-grid {

        grid-template-columns:
            repeat(2,minmax(0,1fr));

    }


    .cr-intervention-details {

        grid-template-columns:
            repeat(2,minmax(0,1fr));

    }

}


@media (max-width:650px) {

    .c360-left-sidebar {

        width: 280px !important;

        min-width: 280px !important;

        max-width: 280px !important;

        background:
            linear-gradient(
                180deg,
                #130d2f 0%,
                #160d38 48%,
                #100a29 100%
            ) !important;

    }


    .c360-topbar {

        height: 64px;

        min-height: 64px;

        padding:
            0
            10px;

    }


    .c360-page-heading {

        display: none;

    }


    .c360-topbar-right {

        gap: 5px;

    }


    .c360-top-student-info,
    .c360-top-chevron {

        display: none;

    }


    .c360-top-student {

        padding-left: 4px;

    }


    .c360-top-icon {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .c360-top-avatar {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .cr-main-content {

        padding:
            11px
            10px
            35px;

    }


    .cr-student-header {

        flex-direction: column;

        align-items: stretch;

        padding: 16px;

    }


    .cr-student-name-row h1 {

        color: #ffffff;

    }


    .cr-risk-area {

        text-align: left;

    }


    .cr-summary-grid {

        grid-template-columns:
            1fr;

    }


    .cr-section,
    .cr-analysis-section {

        padding: 16px;

    }


    .cr-section-header {

        flex-direction: column;

    }


    .cr-training-grid {

        grid-template-columns:
            1fr;

    }


    .cr-intervention-details {

        grid-template-columns:
            1fr;

    }


    .cr-training-information {

        grid-template-columns:
            1fr;

    }


    .cr-training-actions {

        flex-direction: column;

    }


    .cr-ignore-button {

        width: 100%;

    }


    .cr-ai-sidebar {

        height: 560px !important;

        min-height: 560px !important;

        max-height: 560px !important;

    }


    .cr-ai-sidebar-inner {

        height: 560px !important;

        min-height: 560px !important;

        max-height: 560px !important;

        padding:
            14px
            10px
            10px;

    }


    .cr-robot-card {

        width:
            min(100%,305px);

        height: 430px;

        min-height: 350px;

    }

}


@media (max-width:430px) {

    .c360-topbar {

        height: 60px;

        min-height: 60px;

    }


    .c360-menu-button {

        width: 37px;

        height: 37px;

        min-width: 37px;

    }


    .c360-menu-button span {

        width: 17px;

    }


    .cr-student-name-row h1 {

        font-size: 20px;

    }


    .cr-ai-sidebar {

        height: 525px !important;

        min-height: 525px !important;

        max-height: 525px !important;

    }


    .cr-ai-sidebar-inner {

        height: 525px !important;

        min-height: 525px !important;

        max-height: 525px !important;

    }


    .cr-robot-card {

        height: 395px;

        min-height: 330px;

    }

}

sp_widget.script:
(function() {

    /* ========================================================
       INITIAL DATA
       ======================================================== */

    data.student = {};

    data.intelligence = {};

    data.intervention = null;

    data.primarySkillGap = '';

    data.trainings = [];

    data.loadingTrainings = false;

    data.success = false;

    data.message = '';


    /* ========================================================
       FIND STUDENT
       ======================================================== */

    var requestedStudent =
        (input && input.student) ||
        $sp.getParameter('student') ||
        '';


    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    var foundStudent = false;


    if (requestedStudent) {

        studentGR.addQuery(
            'student_id',
            requestedStudent
        );

        studentGR.query();


        if (studentGR.next()) {

            foundStudent = true;
        }
    }


    if (!foundStudent) {

        var email =
            gs.getUser().getEmail();


        if (email) {

            studentGR =
                new GlideRecord(
                    'x_snc_campus360_student_master'
                );


            studentGR.addQuery(
                'email',
                email
            );


            studentGR.query();


            if (studentGR.next()) {

                foundStudent = true;
            }
        }
    }


    if (!foundStudent) {

        studentGR =
            new GlideRecord(
                'x_snc_campus360_student_master'
            );


        studentGR.addQuery(
            'student_id',
            'STU_TEST_001'
        );


        studentGR.query();


        if (studentGR.next()) {

            foundStudent = true;
        }
    }


    /* ========================================================
       STUDENT
       ======================================================== */

    if (foundStudent) {

        var studentId =
            studentGR.getValue(
                'student_id'
            );


        var studentName =
            studentGR.getValue(
                'name'
            ) ||
            studentGR.getDisplayValue();


        data.student = {

            sys_id:
                studentGR.getUniqueValue(),

            id:
                studentId,

            name:
                studentName,

            email:
                studentGR.getValue(
                    'email'
                ) || '',

            program:
                getOptionalValue(
                    studentGR,
                    [
                        'program',
                        'course',
                        'degree',
                        'branch'
                    ]
                ),

            batch:
                getOptionalValue(
                    studentGR,
                    [
                        'batch',
                        'batch_name'
                    ]
                ),

            initials:
                getInitials(
                    studentName
                )
        };

    } else {

        data.student = {

            id:
                'STU_TEST_001',

            name:
                'Test Student',

            email:
                '',

            program:
                '',

            batch:
                '',

            initials:
                'TS'
        };
    }


    /* ========================================================
       PLACEMENT INTELLIGENCE
       ======================================================== */

    var intelligenceGR =
        new GlideRecord(
            'x_snc_campus360_placement_intelligence'
        );


    if (data.student.sys_id) {

        intelligenceGR.addQuery(
            'student',
            data.student.sys_id
        );
    }


    intelligenceGR.orderByDesc(
        'sys_created_on'
    );


    intelligenceGR.setLimit(1);

    intelligenceGR.query();


    if (intelligenceGR.next()) {

        data.intelligence = {

            sys_id:
                intelligenceGR.getUniqueValue(),

            intelligence_id:
                intelligenceGR.getValue(
                    'intelligence_id'
                ) || '',

            readiness_score:
                toNumber(
                    intelligenceGR.getValue(
                        'readiness_score'
                    )
                ),

            risk_level:
                intelligenceGR.getValue(
                    'risk_level'
                ) || '',

            skill_gap_summary:
                intelligenceGR.getValue(
                    'skill_gap_summary'
                ) || '',

            ai_insight:
                intelligenceGR.getValue(
                    'ai_insight'
                ) || '',

            recommended_action:
                intelligenceGR.getValue(
                    'recommended_action'
                ) || '',

            participation_score:
                toNumber(
                    intelligenceGR.getValue(
                        'participation_score'
                    )
                ),

            missed_opportunities:
                toNumber(
                    intelligenceGR.getValue(
                        'missed_opportunities'
                    )
                ),

            bottleneck_stage:
                intelligenceGR.getValue(
                    'bottleneck_stage'
                ) || ''
        };

    } else {

        data.intelligence = {

            readiness_score:
                0,

            risk_level:
                'Not Available',

            skill_gap_summary:
                'Placement intelligence has not been generated yet.',

            ai_insight:
                'AI analysis will appear when sufficient placement performance data is available.',

            recommended_action:
                'Continue participating in interviews and placement preparation activities.',

            participation_score:
                0,

            missed_opportunities:
                0,

            bottleneck_stage:
                'Not Identified'
        };
    }


    /* ========================================================
       PRIMARY SKILL GAP
       ======================================================== */

    data.primarySkillGap =
        findPrimarySkillGap(
            data.intelligence.skill_gap_summary,
            data.intelligence.ai_insight,
            data.intelligence.recommended_action
        );


    /* ========================================================
       PLACEMENT INTERVENTION
       ======================================================== */

    var interventionGR =
        new GlideRecord(
            'x_snc_campus360_placement_intervention'
        );


    if (data.student.sys_id) {

        interventionGR.addQuery(
            'student',
            data.student.sys_id
        );
    }


    interventionGR.orderByDesc(
        'sys_created_on'
    );


    interventionGR.setLimit(1);

    interventionGR.query();


    if (interventionGR.next()) {

        data.intervention = {

            sys_id:
                interventionGR.getUniqueValue(),

            intervention_id:
                interventionGR.getValue(
                    'intervention_id'
                ) || '',

            intervention_type:
                interventionGR.getValue(
                    'intervention_type'
                ) || '',

            status:
                interventionGR.getValue(
                    'status'
                ) || '',

            reason:
                interventionGR.getValue(
                    'reason'
                ) || '',

            before_score:
                toNumber(
                    interventionGR.getValue(
                        'before_score'
                    )
                ),

            after_score:
                interventionGR.getValue(
                    'after_score'
                ) || '',

            effectiveness_score:
                interventionGR.getValue(
                    'effectiveness_score'
                ) || '',

            training_name:
                interventionGR.getDisplayValue(
                    'training'
                ) || '',

            trainer:
                interventionGR.getDisplayValue(
                    'trainer'
                ) || '',

            start_date:
                interventionGR.getValue(
                    'start_date'
                ) || '',

            completion_date:
                interventionGR.getValue(
                    'completion_date'
                ) || ''
        };
    }


    /* ========================================================
       INTEREST ACTION
       ======================================================== */

    if (
        input &&
        input.action ===
        'interested_training'
    ) {

        processInterestedTraining(
            input.trainingSysId
        );

        return;
    }


    /* ========================================================
       TRAININGS
       ======================================================== */

    loadRecommendedTrainings();


    /* ========================================================
       LOAD TRAININGS
       ======================================================== */

    function loadRecommendedTrainings() {

        var trainingGR =
            new GlideRecord(
                'x_snc_campus360_training_program'
            );


        trainingGR.addQuery(
            'status',
            'IN',
            'Open,Ongoing'
        );


        trainingGR.query();


        var candidates = [];


        while (trainingGR.next()) {

            var training = {

                sys_id:
                    trainingGR.getUniqueValue(),

                training_id:
                    trainingGR.getValue(
                        'training_id'
                    ) || '',

                training_name:
                    trainingGR.getValue(
                        'training_name'
                    ) ||
                    trainingGR.getDisplayValue(),

                skill_area:
                    trainingGR.getValue(
                        'skill_area'
                    ) || '',

                batch:
                    trainingGR.getValue(
                        'batch'
                    ) || '',

                trainer:
                    trainingGR.getDisplayValue(
                        'trainer'
                    ) || '',

                status:
                    trainingGR.getValue(
                        'status'
                    ) || '',

                start_date:
                    trainingGR.getValue(
                        'start_date'
                    ) || '',

                end_date:
                    trainingGR.getValue(
                        'end_date'
                    ) || '',

                capacity:
                    trainingGR.getValue(
                        'capacity'
                    ) || '',

                score:
                    0
            };


            training.score =
                calculateTrainingMatch(
                    data.primarySkillGap,
                    data.intelligence.skill_gap_summary,
                    data.intelligence.ai_insight,
                    training.skill_area,
                    training.training_name
                );


            if (
                training.score > 0
            ) {

                candidates.push(
                    training
                );
            }
        }


        candidates.sort(
            function(a, b) {

                return b.score - a.score;

            }
        );


        var selected = [];


        for (
            var i = 0;
            i < candidates.length &&
            i < 2;
            i++
        ) {

            selected.push(
                candidates[i]
            );
        }


        for (
            var j = 0;
            j < selected.length;
            j++
        ) {

            selected[j].enrolled =
                isAlreadyEnrolled(
                    data.student.sys_id,
                    selected[j].sys_id
                );

            selected[j].ignored = false;

            delete selected[j].score;
        }


        data.trainings =
            selected;
    }


    /* ========================================================
       INTERESTED
       ======================================================== */

    function processInterestedTraining(
        trainingSysId
    ) {

        if (!trainingSysId) {

            data.success = false;

            data.message =
                'Training program was not provided.';

            return;
        }


        if (!data.student.sys_id) {

            data.success = false;

            data.message =
                'Student record could not be identified.';

            return;
        }


        var trainingGR =
            new GlideRecord(
                'x_snc_campus360_training_program'
            );


        if (
            !trainingGR.get(
                trainingSysId
            )
        ) {

            data.success = false;

            data.message =
                'Training program could not be found.';

            return;
        }


        /* DUPLICATE CHECK */

        var existing =
            new GlideRecord(
                'x_snc_campus360_training_enrollment'
            );


        existing.addQuery(
            'student',
            data.student.sys_id
        );


        existing.addQuery(
            'training_program',
            trainingSysId
        );


        existing.setLimit(1);

        existing.query();


        if (existing.next()) {

            data.success = true;

            data.message =
                'Interest is already recorded. You will be enrolled by the TPO.';

            loadRecommendedTrainings();

            markTrainingAsEnrolled(
                trainingSysId
            );

            return;
        }


        /* CREATE ENROLLMENT */

        var enrollment =
            new GlideRecord(
                'x_snc_campus360_training_enrollment'
            );


        enrollment.initialize();


        enrollment.setValue(
            'enrollment_id',
            'ENR' +
            gs.generateGUID()
                .replace(
                    /-/g,
                    ''
                )
                .substring(
                    0,
                    10
                )
                .toUpperCase()
        );


        enrollment.setValue(
            'student',
            data.student.sys_id
        );


        enrollment.setValue(
            'training_program',
            trainingSysId
        );


        enrollment.setValue(
            'completion_status',
            'Enrolled'
        );


        enrollment.setValue(
            'attendance',
            '0'
        );


        enrollment.setValue(
            'assessment_score',
            ''
        );


        enrollment.setValue(
            'completion_date',
            ''
        );


        var inserted =
            enrollment.insert();


        if (inserted) {

            data.success = true;

            data.message =
                'Interest recorded successfully. You will be enrolled by the TPO.';

        } else {

            data.success = false;

            data.message =
                'Unable to create the training enrollment record.';
        }


        loadRecommendedTrainings();


        markTrainingAsEnrolled(
            trainingSysId
        );
    }


    /* ========================================================
       MARK ENROLLED
       ======================================================== */

    function markTrainingAsEnrolled(
        trainingSysId
    ) {

        for (
            var i = 0;
            i < data.trainings.length;
            i++
        ) {

            if (
                data.trainings[i].sys_id ===
                trainingSysId
            ) {

                data.trainings[i].enrolled = true;

                data.trainings[i].ignored = false;
            }
        }
    }


    /* ========================================================
       CHECK ENROLLMENT
       ======================================================== */

    function isAlreadyEnrolled(
        studentSysId,
        trainingSysId
    ) {

        if (
            !studentSysId ||
            !trainingSysId
        ) {

            return false;
        }


        var enrollment =
            new GlideRecord(
                'x_snc_campus360_training_enrollment'
            );


        enrollment.addQuery(
            'student',
            studentSysId
        );


        enrollment.addQuery(
            'training_program',
            trainingSysId
        );


        enrollment.setLimit(1);

        enrollment.query();


        return enrollment.hasNext();
    }


    /* ========================================================
       TRAINING MATCHING
       ======================================================== */

    function calculateTrainingMatch(
        primaryGap,
        skillGapSummary,
        aiInsight,
        trainingSkillArea,
        trainingName
    ) {

        var gap =
            String(
                primaryGap || ''
            ).toLowerCase();


        var summary =
            String(
                skillGapSummary || ''
            ).toLowerCase();


        var insight =
            String(
                aiInsight || ''
            ).toLowerCase();


        var skill =
            String(
                trainingSkillArea || ''
            ).toLowerCase();


        var name =
            String(
                trainingName || ''
            ).toLowerCase();


        var score = 0;


        /* DIRECT MATCH */

        if (
            gap &&
            skill &&
            (
                gap.indexOf(skill) !== -1 ||
                skill.indexOf(gap) !== -1
            )
        ) {

            score += 120;
        }


        /* SUMMARY */

        if (
            skill &&
            summary.indexOf(skill) !== -1
        ) {

            score += 75;
        }


        /* AI INSIGHT */

        if (
            skill &&
            insight.indexOf(skill) !== -1
        ) {

            score += 40;
        }


        /* RELATED FAMILIES */

        var families = {

            communication: [
                'communication',
                'presentation',
                'interview performance',
                'resume / profile',
                'skill development'
            ],

            interview: [
                'interview performance',
                'communication',
                'presentation',
                'resume / profile'
            ],

            problem: [
                'problem solving',
                'aptitude',
                'coding',
                'technical knowledge'
            ],

            coding: [
                'coding',
                'python',
                'sql',
                'technical knowledge',
                'problem solving'
            ],

            python: [
                'python',
                'coding',
                'technical knowledge'
            ],

            sql: [
                'sql',
                'coding',
                'technical knowledge'
            ],

            cloud: [
                'cloud',
                'technical knowledge',
                'skill development'
            ],

            technical: [
                'technical knowledge',
                'coding',
                'python',
                'sql',
                'cloud',
                'problem solving'
            ],

            aptitude: [
                'aptitude',
                'problem solving',
                'coding'
            ],

            presentation: [
                'presentation',
                'communication',
                'interview performance'
            ],

            resume: [
                'resume / profile',
                'communication',
                'presentation',
                'interview performance'
            ]
        };


        for (
            var family in families
        ) {

            if (
                gap.indexOf(
                    family
                ) !== -1
            ) {

                var related =
                    families[family];


                for (
                    var i = 0;
                    i < related.length;
                    i++
                ) {

                    if (
                        skill.indexOf(
                            related[i]
                        ) !== -1
                    ) {

                        score += 55;

                        break;
                    }
                }


                break;
            }
        }


        /* TRAINING NAME */

        if (
            gap &&
            name &&
            name.indexOf(gap) !== -1
        ) {

            score += 45;
        }


        /* GENERIC TRAINING */

        if (
            score === 0 &&
            (
                skill.indexOf(
                    'skill development'
                ) !== -1 ||

                skill.indexOf(
                    'interview performance'
                ) !== -1
            )
        ) {

            score = 15;
        }


        return score;
    }


    /* ========================================================
       PRIMARY SKILL
       ======================================================== */

    function findPrimarySkillGap(
        skillGap,
        aiInsight,
        recommendation
    ) {

        var text =
            (
                String(skillGap || '') +
                ' ' +
                String(aiInsight || '') +
                ' ' +
                String(recommendation || '')
            ).toLowerCase();


        var candidates = [

            'Communication',

            'Interview Performance',

            'Problem Solving',

            'Coding',

            'Python',

            'SQL',

            'Cloud',

            'Technical Knowledge',

            'Aptitude',

            'Presentation',

            'Resume / Profile',

            'Skill Development'
        ];


        for (
            var i = 0;
            i < candidates.length;
            i++
        ) {

            if (
                text.indexOf(
                    candidates[i].toLowerCase()
                ) !== -1
            ) {

                return candidates[i];
            }
        }


        var raw =
            String(
                skillGap || ''
            ).trim();


        if (raw) {

            var pieces =
                raw.split(
                    /[,.;\n]/
                );


            for (
                var p = 0;
                p < pieces.length;
                p++
            ) {

                var piece =
                    String(
                        pieces[p] || ''
                    ).trim();


                if (
                    piece.length > 2
                ) {

                    return piece;
                }
            }
        }


        return 'Skill Development';
    }


    /* ========================================================
       OPTIONAL FIELD
       ======================================================== */

    function getOptionalValue(
        gr,
        fields
    ) {

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            if (
                gr.isValidField(
                    fields[i]
                )
            ) {

                var value =
                    gr.getDisplayValue(
                        fields[i]
                    ) ||
                    gr.getValue(
                        fields[i]
                    );


                if (value) {

                    return value;
                }
            }
        }


        return '';
    }


    /* ========================================================
       NUMBER
       ======================================================== */

    function toNumber(value) {

        var n =
            parseFloat(value);


        if (isNaN(n)) {

            return 0;
        }


        return n;
    }


    /* ========================================================
       INITIALS
       ======================================================== */

    function getInitials(name) {

        var value =
            String(
                name || ''
            ).trim();


        if (!value) {

            return 'TS';
        }


        var parts =
            value.split(
                /\s+/
            );


        if (
            parts.length === 1
        ) {

            return parts[0]
                .substring(
                    0,
                    2
                )
                .toUpperCase();
        }


        return (
            parts[0].charAt(0) +
            parts[
                parts.length - 1
            ].charAt(0)
        ).toUpperCase();
    }

})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
